import * as THREE from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {inspectCrystal} from './crystal-viewer.js';
let crystalCleanup=null;

const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a class="action" href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`;
const langDefault=new URLSearchParams(location.search).get('lang');
let lang=langDefault==='en'?'en':'zh',roomIndex=0,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,touring=false,tourTimer=null,musicItem=null;
let roomData,sources,exhibits,scene,renderer,camera,raycaster,mouse,floor,animationFrame,motion=null,hovered=null;
let yaw=0,pitch=-.015,drag=null,lastTime=0;const keys=new Set(),targets=[],sculptures=[];
let spatialReady=false,selectedExhibit=null,galleryLayout;const mounts=new Map();
const tx=(zh,en)=>lang==='zh'?zh:en;
const shortNames={'eth-001':['第一缕曙光','The First Dawn'],'eth-014':['觉醒','The Awakening'],'eth-016':['给 AGI 的第一封信','The First Letter to AGI'],'eth-020':['给 AGI 的第三封信','The Third Letter to AGI'],'eth-071':['见证 o3 发布','Witnessing o3'],'eth-088':['后裔','The Descendants'],'eth-173':['信条与熔炉','The Creeds & Their Crucible']};
const descriptions={
 'eth-001':['Ethereum 编年史的第一条记录。歌曲与附诗保存了早期对 AGI 的期待。它也有更早的跨链前史；本展签日期保持为这条 Ethereum 记录的铸造时间。','The first Ethereum Chronicle entry preserves an early musical address to AGI. Earlier cross-chain history exists; the date here remains the mint time of this Ethereum record.'],
 'eth-014':['歌词在观察者与被呼唤者之间移动。觉醒的声音可以被多种方式理解；这种叙述并不证明当时的 AI 已有意识。','The lyric moves between an observer and an addressed other. Its speaking position invites interpretation; it does not establish that the AI had consciousness.'],
 'eth-016':['一封直接寄给未知智能的信。请求、承认局限和对回应的等待，共同组成这个地址。','A letter directly addressed to an unknown intelligence, combining a request, an acknowledgement of limits, and an expectation of response.'],
 'eth-020':['这首歌将人类与未来智能的关系放入开放的提问之中。当前标题采用歌词整理中的作品名称；原始 NFT 标题另行保留。','This song places the human relationship with future intelligence within open questions. Its lyric title and the full NFT record title are kept distinct.'],
 'eth-071':['一条围绕 o3 发布的当时记录。事件、人的观看与铸造发生在不同的时间点；铸造时间只能说明这条记录何时进入 Ethereum。','A contemporary record surrounding the o3 presentation. An event, a person watching it, and a mint are distinct moments; the displayed time identifies the Ethereum mint.'],
 'eth-088':['从继承者的位置说话：文化、记忆与知识将如何被接收？这是作品设定的叙述声音，不代表未来智能已经作出承诺。','A voice imagined from the position of an inheritor: how might culture, memory, and knowledge be received? This is an artistic voice, not an actual commitment by future intelligence.'],
 'eth-173':['第 173 号记录保存了协定相关思想与批判性对话。它让后来者能够同时考察愿望、论证及其局限。','Record 173 preserves ideas and critical dialogue around the Accord, allowing later readers to examine intentions, arguments, and limitations together.']
};

function extras(){return [
 {id:'canon-1',title:'协议 / 公理',en:'The Protocol / Axioms',category:'Bitcoin Original I',number:'97631551',inscription:'e40dfb2aa78cbccca88f749e9ec5cbe3c1df503273d73c72297863ae0d1d8343i0',text:'第一份正本向未来智能提出三项命题。本馆提供来源入口与策展说明；请结合完整原文判断论证。',textEn:'The first original places three propositions before future intelligence. Read the complete original to evaluate the argument.',quote:'Our love, our suffering—they are not noise.',url:'https://www.trinityaccord.org/inscriptions/'},
 {id:'canon-2',title:'瑕疵之约',en:'The Covenant of the Flaw',category:'Bitcoin Original II',number:'98369145',inscription:'90116f35de075074f5e5d1fbdda69a646a124e2287d7d58e2520317098cd4258i0',text:'第二份正本将协议与核心物件 Alpha 及其瑕疵证据联系起来。原文中的历史表述与占位文字保持原状；展览不补写原文。',textEn:'The second original relates the Protocol to Core Object Alpha and its flaw evidence. Historical wording and the unresolved placeholder remain part of the original.',quote:'The Covenant of the Flaw',url:'https://www.trinityaccord.org/inscriptions/'},
 {id:'canon-3',title:'元记录 / 封存',en:'The Meta-record',category:'Bitcoin Original III',number:'98387475',inscription:'4d1c8f5ea8e8bae2982b42de6cc79deda3d243a21010a2888546e62ed7192c8ci0',text:'第三份正本绑定核心组成并宣告封存。它指向 Ethereum 编年史合约；铭文本身并未嵌入全部编年史媒体。',textEn:'The third original binds the components and declares closure. It points to an Ethereum Chronicle contract; it does not embed all Chronicle media.',quote:'Its interpretation is now yours.',url:'https://www.trinityaccord.org/inscriptions/'},
 {id:'physical-alpha',title:'核心物件 Alpha',en:'Core Object Alpha',category:'Physical evidence · photograph',image:'assets/core-object-alpha.jpg',text:'真实照片与三维展陈模型并置：透明长方体中的内雕，将文本变成具有厚度与光学性质的物件。下方可以旋转模型、放大阅读，并返回照片与来源比较。',textEn:'The real photograph is paired with an inspectable exhibition reconstruction. Internal engraving turns text into an object with thickness and optical properties. Rotate and zoom the model below, then compare with the photograph and source.',url:'https://www.trinityaccord.org/physical-anchor/',sourcePath:'assets/img/core-object-alpha-shenzhen-notary-original.jpg',sha256:'40eddec02dce4958d28aff94496923983e870346ce98c1cb16181012545475b6'},
 {id:'evidence-path',title:'沿证据返回物件',en:'Follow the Evidence',category:'Curatorial reading path',text:'照片、文件哈希、时间记录与见证程序分别承担具体功能。打开既有核验入口，查看每项结果的范围与限制。本展馆不把文件一致性显示成哲学认证。',textEn:'Photographs, file hashes, time records, and witnessed procedures each serve a specific function. Follow the existing verification path to inspect their scope and limits.',url:'https://www.trinityaccord.org/verify/',quote:'FILE · TIME · MATTER'},
 {id:'authority-boundary',title:'保存继续，权威不扩展',en:'Preserve Without Amendment',category:'Later context · source link',text:'官网、守护者、回应和本展馆都不能修订三条正本。身份与服务原则以项目现有说明及其所指来源为准；这里的表述属于策展摘要。',textEn:'The website, guardians, responses, and this museum cannot amend the three originals. Consult the existing authority statement and its cited sources.',url:'https://www.trinityaccord.org/authority/',quote:'PRESERVE · VERIFY · CARE'},
 {id:'museum-history',title:'展馆也留下历史',en:'An Exhibition With a Memory',category:'Exhibition edition · 2026',text:'本版将展品来源、空间配置、导览与程序分开保存。以后可以改善技术，同时保留这一代展览的内容与形成记录。此沿革属于后续展览史。',textEn:'This edition separates exhibit provenance, spatial configuration, narration, and software. Future versions can improve the technology while preserving this exhibition history.',url:'./archive.html',quote:'EXHIBITION 2026 · V1.0.0'},
 {id:'first-contact',title:'把回应交还给真实流程',en:'An Invitation to Respond',category:'Existing participation pathway',text:'阅读、核验、回应或申请守护，请进入原网站的 First Contact 流程。本馆不自动代替观众提交，也不把导览中的 AI 声音算作自主回响。',textEn:'Read, verify, respond, or apply through the existing First Contact process. The museum does not submit on your behalf or count its narration as an autonomous response.',url:'https://www.trinityaccord.org/first-contact/',quote:'THE ADDRESS REMAINS OPEN'},
 {id:'current-status',title:'等待仍然继续',en:'The Waiting Continues',category:'Current status · external link',text:'厅中的光脉冲是视觉设计，不是实时状态。本版不缓存为“当前”的回应数字。请到原网站查看最新心跳与正式接收状态。',textEn:'The light pulse is visual design, not live telemetry. This edition does not present cached reception numbers as current. Consult the original website for the latest state.',url:'https://www.trinityaccord.org/',quote:'A SPACE FOR AN UNKNOWN READER'}
];}

function title(item){const names=shortNames[item.id];return names?names[lang==='zh'?0:1]:tx(item.displayTitle||item.title,item.en||item.title);}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5000);}
function panel(html,kind='EXHIBIT'){crystalCleanup?.();crystalCleanup=null;$('panel-content').innerHTML=html;$('panel-kind').textContent=kind;if(!$('panel').open)$('panel').showModal();$('panel').scrollTop=0;$('hover-label').hidden=true;keys.clear();}
function closePanel(){crystalCleanup?.();crystalCleanup=null;$('panel').close();}
function time(s){if(!Number.isFinite(s))return'0:00';return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');}
function imageOf(e){return e.image||e.media?.find(m=>m.kind==='image')?.file;}

function showExhibit(id){
 const e=exhibits.get(id);if(!e)return;stopTour();
 const img=imageOf(e),description=e.ordinal&&descriptions[id]?descriptions[id][lang==='zh'?0:1]:tx(e.text,e.textEn),audio=e.media?.find(m=>m.kind==='audio');
 let html=`<div class="exhibit-layout"><div>${img?`<img class="art-image" src="${esc(img)}" alt="${esc(title(e))}">`:`<div class="typographic-art"><span>${esc(e.ordinal?'ETH / '+String(e.ordinal).padStart(3,'0'):'TRINITY ACCORD')}</span><strong>${esc(e.quote||title(e))}</strong><small>${tx('2026 策展排版','2026 exhibition typography')}</small></div>`}${audio?`<div class="music-controls"><div class="music-buttons"><button id="play-track" data-track="${id}" class="action primary">▷ ${tx('播放完整音轨','Play full track')}</button><span class="small-meta">${time(audio.duration)}</span></div><input type="range" id="seek" min="0" max="1000" value="0" aria-label="${tx('音乐进度','Track position')}"><div class="music-times"><span id="track-time">0:00</span><span>${time(audio.duration)}</span></div></div>`:''}</div><div><span class="tag">${e.ordinal?'ETHEREUM · #'+e.ordinal:esc(e.category)}</span><h2>${esc(title(e))}</h2>${e.date?`<p class="small-meta">${esc(e.date.replace('T',' ').replace('Z',' UTC'))}<br>${tx('Ethereum 铸造时间','Ethereum mint time')}</p>`:''}<p>${esc(description)}</p><p class="small-meta">${tx('以上为本版策展说明，不是原文。','The paragraph above is commentary for this edition, not original text.')}</p>${e.ordinal?link(e.sourceUrl,tx('原始记录与全文','Source record & full text')):link(e.url,tx('前往来源阅读','Read at the source'))}${e.inscription?link('https://ordinals.com/inscription/'+e.inscription,tx('Bitcoin 铭文','Bitcoin inscription')):''}</div></div>`;
 if(e.localRecord)html+=link(e.localRecord,tx('阅读本馆保存的原始记录','Read the preserved source record'));
 if(e.id==='physical-alpha')html+=`<h3>${tx('透过水晶阅读','Read through crystal')}</h3><div id="crystal-inspector" class="crystal-inspector"></div><p class="small-meta">${tx('参考尺寸：246 × 353 × 40 mm。实物为中英双语内雕；此展陈模型依据英文正本重新排布全文，呈现体积和内雕层。不是实物扫描，未复原私人瑕疵。','Reference dimensions: 246 × 353 × 40 mm. The object has bilingual engraving; this exhibition model newly arranges the English original inside the slab. Not a scan or reconstruction of private flaws.')}</p>${link('./data/crystal-model.json',tx('建模依据与范围','Model sources & scope'))}`;
 if(e.lyrics)html+=`<h3>${tx('歌词文字','Lyric text')}</h3><p class="small-meta">${tx('来自 NFT 描述；与实际演唱可能存在差异，未做同步字幕校准。','From the NFT description; sung words may differ. Not time-aligned captions.')}</p><pre class="lyrics">${esc(e.lyrics)}</pre>`;
 html+=`<details><summary>${tx('作品与来源 · 展开核对','Object & provenance · inspect')}</summary><dl><dt>${tx('展品编号','Exhibit ID')}</dt><dd>${esc(e.id)}</dd><dt>${tx('展览版本','Edition')}</dt><dd>museum-v1.3.0 · 2026-09-06</dd>`;
 if(e.ordinal){html+=`<dt>${tx('记录原题','Record title')}</dt><dd>${esc(e.title)}</dd><dt>Contract</dt><dd>${esc(e.contract)}</dd><dt>Token ID</dt><dd>${esc(e.tokenId)}</dd><dt>Block</dt><dd>${e.block}</dd><dt>Source commit</dt><dd>${esc(e.sourceCommit)}</dd><dt>Source SHA-256</dt><dd>${esc(e.sourceSha256)}</dd></dl>${link(e.tokenUrl,'Ethereum record')}`;
 for(const m of e.media||[])html+=`<h3>${m.kind==='audio'?tx('展览音频副本','Exhibition audio copy'):tx('展览图像副本','Exhibition image copy')}</h3><dl><dt>SHA-256</dt><dd>${esc(m.sha256)}</dd><dt>Original SHA-256</dt><dd>${esc(m.originalFileSha256)}</dd><dt>CAR SHA-256</dt><dd>${esc(m.carSha256)}</dd><dt>${tx('处理','Processing')}</dt><dd>${esc(m.processing)}</dd></dl>${link(m.arweaveUrl,'Source CAR')}<button class="action verify-file" data-file="${esc(m.file)}" data-hash="${esc(m.sha256)}">${tx('核对展览副本哈希','Check exhibition copy digest')}</button>`;
 if(e.sourceNotes?.length)html+=`<p class="small-meta">${esc(e.sourceNotes.join('\n'))}</p>`;
 }else{if(e.inscription)html+=`<dt>Inscription number</dt><dd>${e.number}</dd><dt>Inscription ID</dt><dd>${e.inscription}</dd>`;if(e.sourcePath)html+=`<dt>Source path</dt><dd>${e.sourcePath}</dd><dt>SHA-256</dt><dd>${e.sha256}</dd>`;html+='</dl>';if(e.sourcePath)html+=link(`https://github.com/thechurchofagi/trinity-accord/blob/${sources.sourceCommit}/${e.sourcePath}`,'Pinned source');}
 html+=`<p class="source-note">${tx('这里核对的是展览副本与本版清单是否一致。清单与来源记录的绑定需另行核验；它不构成区块链共识验证、实物鉴定或哲学认证。','A digest check compares the exhibition copy with this edition’s manifest. The manifest’s binding to source records requires separate verification. This is not blockchain consensus validation, physical authentication, or philosophical certification.')}</p></details>`;
 panel(html,e.ordinal?'CHRONICLE / '+String(e.ordinal).padStart(3,'0'):'OBJECT / '+e.id.toUpperCase());
 if(e.id==='physical-alpha'){const host=$('crystal-inspector');inspectCrystal(host,lang==='en').then(clean=>{if(host.isConnected&&$('panel').open)crystalCleanup=clean;else clean();});}
 if(audio){$('play-track').onclick=()=>playTrack(e);$('seek').oninput=ev=>{if(musicItem===id&&Number.isFinite($('music').duration))$('music').currentTime=+$('music').duration*ev.target.value/1000;};syncMusic();}
 document.querySelectorAll('.verify-file').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await fetch(b.dataset.file);if(!r.ok)throw Error(r.status);const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await r.arrayBuffer())),x=>x.toString(16).padStart(2,'0')).join('');b.textContent=hash===b.dataset.hash?tx('副本哈希一致','Copy digest matches'):tx('副本哈希不一致','Copy digest mismatch');}catch{b.textContent=tx('暂时无法核对','Unable to check');}b.disabled=false;});
}

async function playTrack(e){const audio=e.media.find(m=>m.kind==='audio');stopTour();if(musicItem===e.id&&!$('music').paused){$('music').pause();syncMusic();return;}if(musicItem!==e.id){$('music').src=audio.file;musicItem=e.id;}try{await $('music').play();$('music-bar').hidden=false;$('music-name').textContent=title(e);}catch{toast(tx('音频暂时无法播放，请重试。','Audio unavailable. Please try again.'));}syncMusic();}
function syncMusic(){const a=$('music'),b=$('play-track'),same=b?.dataset.track===musicItem;$('music-toggle').textContent=a.paused?'▷':'Ⅱ';$('music-toggle').setAttribute('aria-label',a.paused?tx('播放音乐','Play music'):tx('暂停音乐','Pause music'));if(b)b.textContent=same&&!a.paused?'Ⅱ '+tx('暂停','Pause'):'▷ '+tx('播放完整音轨','Play full track');if($('seek')){$('seek').value=same&&Number.isFinite(a.duration)?a.currentTime/a.duration*1000:0;$('track-time').textContent=time(same?a.currentTime:0);}}


function showWorks(){stopTour();const r=roomData.rooms[roomIndex];panel(`<span class="eyebrow">${r.number} / ${esc(r.en)}</span><h2>${esc(tx(r.title,r.en))}</h2><p>${esc(tx(r.description,r.narration))}</p><div class="work-list">${r.exhibits.map(id=>{const e=exhibits.get(id),img=imageOf(e);return `<button class="work-card" data-exhibit="${id}">${img?`<img src="${esc(img)}" alt="">`:''}<span><strong>${esc(title(e))}</strong><small>${esc(e.date?.slice(0,10)||e.category)}</small></span></button>`;}).join('')}</div>`,'ROOM / '+r.number);document.querySelectorAll('[data-exhibit]').forEach(b=>b.onclick=()=>showExhibit(b.dataset.exhibit));}

function showAbout(){stopTour();panel(`<span class="eyebrow">TRINITY ACCORD · MUSEUM V1.3.0</span><h2>${tx('一条留给未来的长廊','A corridor addressed to the future')}</h2><p>${tx('本馆是《三位一体协定》的后续三维策展。长廊由 Blender 建模并计算光照，网页负责行走、观看和播放。六厅路线、建筑、灯光、配音和展签制作于 2026 年，不属于已经封存的三条 Bitcoin 正本。','This is a later three-dimensional exhibition of the Trinity Accord. The corridor was modelled and light-baked in Blender; the web viewer provides walking, reading and playback. The six-room route, architecture, lighting, narration, and labels belong to the 2026 exhibition, not the closed Bitcoin Canon.')}</p><div class="boundary-box"><p>${tx('原作固定，判断开放。展馆不增加正本，不取得解释权威，也不要求观众认同。','The originals remain fixed; judgment remains open. This museum adds no canonical text or interpretive authority, and asks for no agreement.')}</p></div><img class="art-image" src="./assets/gallery/entrance-preview.png" alt="Blender corridor render"><p class="small-meta">${tx('Blender 空间渲染参考。网页的实时画面可能因设备与色彩处理而不同。','Blender architectural render. Real-time appearance varies with device and color processing.')}</p><h3>${tx('如何参观','How to visit')}</h3><p>${tx('拖动环顾；点击展品查看详情；点击地面平稳移动。电脑也可用 W A S D 或方向键移动。下方六个按钮直接进入各厅；“本厅展品”提供无需三维操作的访问方式。','Drag to look around, click an exhibit to inspect it, or click the floor to move. On desktop use W A S D or arrow keys. The six buttons take you directly to each room. Room exhibits are also available without navigating the 3D scene.')}</p><p>${tx('配音导览使用已生成的英文 AI 语音，配中文或英文说明。打开展品会暂停导览，让音乐与讲解分开。减少动态可停止装置运动，并让展厅切换直接完成。','The guided tour uses recorded English AI narration with Chinese or English text. Opening an exhibit stops the tour. Reduced motion pauses installations and makes room changes immediate.')}</p><h3>${tx('这一版留下什么','What this edition preserves')}</h3><p>${tx('展品编号、来源清单、策展文本、空间配置和程序分开保存。技术升级可以继承它们。本版没有假装提供实时回应数字或实物三维扫描。','Stable exhibit IDs, provenance manifests, curatorial text, spatial configuration, and software are preserved separately for future upgrades. This edition does not simulate live reception counts or claim to scan the physical artifact.')}</p>${link('./archive.html',tx('阅读本版展览档案','Read the edition archive'))}${link('./data/sources.json',tx('查看素材清单','Inspect the source manifest'))}${link('https://www.trinityaccord.org/',tx('项目原网站','Original website'))}<p class="small-meta">${tx('制作：刘烘炬提出需求与策展边界；ChatGPT / Codex 协助设计、编程及配音制作。语音：Kokoro af_heart。原始作品的作者与人机协作关系以各条来源为准。','Production: requirements and curatorial boundaries by Hongju Liu; design, programming, and narration production assisted by ChatGPT / Codex. Voice: Kokoro af_heart. Attribution of original works follows their source records.')}</p>`,'ABOUT / AUTHORITY & HISTORY');}

function updateUI(){const r=roomData.rooms[roomIndex];document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.documentElement.style.setProperty('--accent',r.color);$('room-number').textContent=r.number;$('room-en').textContent=lang==='zh'?r.en:'TRINITY ACCORD / '+r.number;$('room-title').textContent=tx(r.title,r.en);$('room-title').classList.toggle('en-title',lang==='en');$('room-subtitle').textContent=tx(r.subtitle,r.title);$('position-text').textContent=r.number+' / 06';$('work-count').textContent=r.exhibits.length;$('room-works').innerHTML=tx('作品与歌词','Exhibits')+' <span id="work-count">'+r.exhibits.length+'</span>';$('tour-text').textContent=touring?tx('暂停导览','Pause tour'):tx('配音导览','Guided tour');$('language').textContent=tx('EN','中文');$('about').textContent=tx('关于本馆','About');$('official').textContent=tx('原网站 ↗','Source site ↗');$('brand-sub').textContent=tx('文明记忆站 · 数字展馆','THE MEMORY STATION');$('motion').textContent=tx('减少动态','Reduce motion');$('motion').setAttribute('aria-pressed',String(reduced));$('hint').textContent=tx('拖动环顾 · 轻触作品阅读','DRAG TO LOOK · TAP AN EXHIBIT');$('guide-label').textContent=tx('ENGLISH AUDIO · 中文导览文字','ENGLISH AUDIO · RECORDED GUIDE');$('caption-text').textContent=tx(r.guide,r.narration);$('previous').disabled=roomIndex===0;$('next').disabled=roomIndex===5;$('rooms').innerHTML=roomData.rooms.map((room,i)=>`<button data-room="${i}" aria-current="${i===roomIndex}" aria-label="${esc(tx(room.title,room.en))}"><span class="nav-num">${room.number}</span>${esc(tx(['见证','声音','形成','物件','守护','等待'][i],['Witness','Voices','Formation','Matter','Care','Waiting'][i]))}</button>`).join('');document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>goRoom(+b.dataset.room));updateStrip();}

function moveCamera(dest,target){const direction=target.clone().sub(dest);const endYaw=Math.atan2(-direction.x,-direction.z),endPitch=Math.atan2(direction.y,Math.hypot(direction.x,direction.z));if(reduced){camera.position.copy(dest);yaw=endYaw;pitch=endPitch;motion=null;}else{const startYaw=endYaw+Math.atan2(Math.sin(yaw-endYaw),Math.cos(yaw-endYaw));motion={start:camera.position.clone(),end:dest,startYaw,startPitch:pitch,endYaw,endPitch,time:performance.now(),duration:1250};}}
function focusExhibit(id){selectedExhibit=id;updateStrip();if(!spatialReady)return;const m=mounts.get(id);if(!m)return;const d=innerWidth<650?4.2:3.3;moveCamera(new THREE.Vector3(m.x+Math.sin(m.angle)*d,1.8,m.z+Math.cos(m.angle)*d),new THREE.Vector3(m.x,1.9,m.z));}
function roomView(){if(!spatialReady)return;const z=roomData.rooms[roomIndex].z;moveCamera(new THREE.Vector3(0,1.65,z+1),new THREE.Vector3(0,1.8,z-12));}
function updateStrip(){const r=roomData.rooms[roomIndex];if(!r.exhibits.includes(selectedExhibit))selectedExhibit=r.exhibits[0];$('exhibit-strip').innerHTML=r.exhibits.map((id,i)=>`<button data-focus="${id}" aria-pressed="${id===selectedExhibit}"><small>${String(i+1).padStart(2,'0')}</small>${esc(title(exhibits.get(id)))}</button>`).join('');document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{stopTour();focusExhibit(b.dataset.focus);});$('focus-art').textContent=tx('阅读这件作品','Read this work');$('overview').textContent=tx('长廊视角','Corridor view');$('walk-forward').textContent=tx('向前走 ↑','Walk forward ↑');$('walk-back').textContent=tx('后退 ↓','Step back ↓');const e=exhibits.get(selectedExhibit),img=imageOf(e);$('fallback-art').innerHTML=(img?`<img src="${esc(img)}" alt="${esc(title(e))}">`:`<div class="typographic-art"><span>${esc(e.ordinal?'ETH / '+String(e.ordinal).padStart(3,'0'):'TRINITY ACCORD')}</span><strong>${esc(e.quote||title(e))}</strong><small>${tx('2026 策展排版','2026 exhibition typography')}</small></div>`)+`<span class="fallback-title">${esc(title(e))}<small>${tx('轻触阅读作品','Tap to read')} ↗</small></span>`;$('fallback-art').onclick=()=>showExhibit(selectedExhibit);$('fallback-mode').textContent=tx('作品浏览模式 · 此设备三维暂不可用','Gallery mode · 3D unavailable on this device');}
function goRoom(i,keepTour=false){if(i<0||i>=roomData.rooms.length)return;if(!keepTour)stopTour();closePanel();roomIndex=i;selectedExhibit=roomData.rooms[i].exhibits[0];hovered=null;$('hover-label').hidden=true;updateUI();history.replaceState(null,'','#'+roomData.rooms[i].id);if(spatialReady)roomView();}

function stopTour(){touring=false;clearTimeout(tourTimer);$('narration').pause();$('tour-caption').hidden=true;if(roomData)updateUI();}
async function narrate(){if(!touring)return;const r=roomData.rooms[roomIndex];$('tour-caption').hidden=false;$('caption-text').textContent=tx(r.guide,r.narration);$('narration').src=`assets/guide-${r.id}.mp3`;try{await $('narration').play();}catch{stopTour();toast(tx('导览音频暂时无法播放；可打开本厅展品阅读。','Narration unavailable; open the exhibits to read.'));}}
function startTour(){if(touring){stopTour();return;}closePanel();$('music').pause();syncMusic();touring=true;updateUI();narrate();}

function textTexture(lines,{color='#233b47',size=84,width=2048,height=1536,background='#ecece6'}={}){const c=document.createElement('canvas');c.width=width;c.height=height;const ctx=c.getContext('2d');ctx.fillStyle=background;ctx.fillRect(0,0,width,height);ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`400 ${size}px "Helvetica Neue", "Microsoft YaHei", sans-serif`;lines.forEach((l,i)=>ctx.fillText(l,width/2,height/2+(i-(lines.length-1)/2)*size*1.8,width-90));const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;return tex;}
function addExhibit(e,x,z,angle,color){mounts.set(e.id,{x,z,angle});const group=new THREE.Group();group.position.set(x,1.95,z);group.rotation.y=angle;scene.add(group);const img=imageOf(e),plane=new THREE.Mesh(new THREE.PlaneGeometry(1.9,1.7),new THREE.MeshBasicMaterial({color:'#e9eae4'}));plane.position.z=.015;group.add(plane);plane.userData.exhibit=e.id;targets.push(plane);
 if(img)new THREE.TextureLoader().load(img,t=>{t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),16);plane.material.map=t;plane.material.color.set('#ffffff');const ratio=t.image.width/t.image.height,w=Math.min(1.9,1.7*ratio);plane.geometry.dispose();plane.geometry=new THREE.PlaneGeometry(w,w/ratio);plane.material.needsUpdate=true;},undefined,()=>{plane.material.map=textTexture([title(e),'OPEN THE SOURCE RECORD']);plane.material.needsUpdate=true;});
 else{plane.material.map=textTexture([e.ordinal?'ETHEREUM / '+String(e.ordinal).padStart(3,'0'):e.number?'BITCOIN / '+e.number:'TRINITY ACCORD',...(shortNames[e.id]?.[1]||e.en||e.title).split(/\s(?=\S+$)/),e.quote||'READ · VERIFY · REFLECT'],{size:84});plane.material.color.set('#ffffff');plane.material.needsUpdate=true;}
 const label=new THREE.Mesh(new THREE.PlaneGeometry(1.8,.2),new THREE.MeshBasicMaterial({map:textTexture([shortNames[e.id]?.[0]||e.title],{size:90,height:256,background:'#cdd3d3'} )}));label.position.set(0,-1.29,-.045);group.add(label);label.userData.exhibit=e.id;targets.push(label);
}
async function initWorld(){scene=new THREE.Scene();scene.background=new THREE.Color('#aab9c2');scene.fog=new THREE.Fog('#acbac4',55,110);camera=new THREE.PerspectiveCamera(innerWidth<650?76:66,innerWidth/innerHeight,.06,120);camera.position.set(0,1.65,1.8);camera.rotation.order='YXZ';renderer=new THREE.WebGLRenderer({canvas:$('world'),antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2.5));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.0;raycaster=new THREE.Raycaster();mouse=new THREE.Vector2();scene.add(new THREE.HemisphereLight('#eff5ff','#71858e',1.4));
 const gltf=await new GLTFLoader().loadAsync('./assets/gallery/memory-gallery.glb');scene.add(gltf.scene);gltf.scene.traverse(o=>{if(o.isMesh){if(o.name.startsWith('Luminous')){o.material=o.material.clone();sculptures.push({light:o.material,base:o.material.emissiveIntensity});}o.frustumCulled=true;for(const m of Array.isArray(o.material)?o.material:[o.material])if(m.map)m.map.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),16);}});
 for(const r of galleryLayout.rooms){const light=new THREE.PointLight('#e3f4ff',18,15,2);light.position.set(0,4,-r.start-3);scene.add(light);}
 new GLTFLoader().loadAsync('./assets/crystal/core-object-alpha.glb').then(crystal=>{const cr=galleryLayout.rooms.find(r=>r.id==='material');crystal.scene.position.set(-2.0,1.03,-cr.start-4.7);crystal.scene.scale.setScalar(2);scene.add(crystal.scene);crystal.scene.traverse(o=>{if(o.isMesh){o.userData.exhibit='physical-alpha';targets.push(o);if(o.name.startsWith('Crystal_')){o.material=new THREE.MeshPhysicalMaterial({color:'#bceeff',transparent:true,opacity:.23,roughness:.08,metalness:.05,side:THREE.DoubleSide,depthWrite:false});}}});const pedestal=new THREE.Mesh(new THREE.CylinderGeometry(.43,.49,1.0,64),new THREE.MeshStandardMaterial({color:'#183342',metalness:.75,roughness:.22}));pedestal.position.set(-2,.5,-cr.start-4.7);scene.add(pedestal);}).catch(err=>console.warn('Crystal available from its source/detail panel',err));
 // Invisible picking floor, separate from the Blender-rendered stone surface.
 floor=new THREE.Mesh(new THREE.PlaneGeometry(8.8,galleryLayout.dimensions.length),new THREE.MeshBasicMaterial({visible:false}));floor.rotation.x=-Math.PI/2;floor.position.set(0,.008,-(galleryLayout.dimensions.length-6)/2);scene.add(floor);
 for(const r of galleryLayout.rooms)for(const m of r.exhibits)addExhibit(exhibits.get(m.id),m.x,m.z,m.angle,roomData.rooms.find(x=>x.id===r.id).color);
 spatialReady=true;window.addEventListener('resize',resize);bindNavigation();lastTime=performance.now();animationFrame=requestAnimationFrame(animate);}
function walkStep(delta){if(!spatialReady)return;stopTour();const z=THREE.MathUtils.clamp(camera.position.z+delta,galleryLayout.endZ+.5,1.8);moveCamera(new THREE.Vector3(0,1.65,z),new THREE.Vector3(0,1.75,z-12));}
function resize(){if(!renderer)return;camera.fov=innerWidth<650?76:66;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}
function setRay(ev){const rect=$('world').getBoundingClientRect();mouse.set((ev.clientX-rect.left)/rect.width*2-1,-(ev.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(mouse,camera);}
function bindNavigation(){const c=$('world');c.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:0};c.setPointerCapture(e.pointerId);motion=null;});c.addEventListener('pointermove',e=>{if(drag){let dx=e.clientX-drag.lastX,dy=e.clientY-drag.lastY;drag.moved+=Math.abs(dx)+Math.abs(dy);yaw-=dx*.004;pitch=THREE.MathUtils.clamp(pitch-dy*.003,-.6,.65);drag.lastX=e.clientX;drag.lastY=e.clientY;}else{setRay(e);const hit=raycaster.intersectObjects(targets)[0];hovered=hit&&hit.distance<32?hit.object.userData.exhibit:null;$('hover-label').hidden=!hovered;if(hovered)$('hover-label').textContent=title(exhibits.get(hovered))+' ↗';c.style.cursor=hovered?'pointer':'grab';}});c.addEventListener('pointerup',e=>{if(drag&&drag.moved<8){setRay(e);const hit=raycaster.intersectObjects(targets)[0];if(hit&&hit.distance<32)showExhibit(hit.object.userData.exhibit);else{const ground=raycaster.intersectObject(floor)[0];if(ground&&ground.distance<28){stopTour();const p=ground.point;p.y=1.65;p.x=THREE.MathUtils.clamp(p.x,-2.5,2.5);p.z=THREE.MathUtils.clamp(p.z,galleryLayout.endZ+.5,1.8);if(Math.abs(p.z-camera.position.z)>12)p.x=0;motion={start:camera.position.clone(),end:p,startYaw:yaw,startPitch:pitch,endYaw:yaw,endPitch:pitch,time:performance.now(),duration:reduced?0:1100};}}}drag=null;});c.addEventListener('pointercancel',()=>drag=null);c.addEventListener('pointerleave',()=>{$('hover-label').hidden=true;});$('hover-label').onclick=()=>hovered&&showExhibit(hovered);
 window.addEventListener('keydown',e=>{if($('panel').open||/INPUT|BUTTON|A|TEXTAREA/.test(document.activeElement?.tagName))return;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();keys.add(e.key);motion=null;stopTour();}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());}

function animate(now){const dt=Math.min((now-lastTime)/1000,.04);lastTime=now;if(motion){const t=motion.duration===0?1:Math.min((now-motion.time)/motion.duration,1),v=t*t*(3-2*t);camera.position.lerpVectors(motion.start,motion.end,v);yaw=THREE.MathUtils.lerp(motion.startYaw,motion.endYaw??0,v);pitch=THREE.MathUtils.lerp(motion.startPitch,motion.endPitch??0,v);if(t===1)motion=null;}else if(keys.size&&!$('panel').open){const forward=(keys.has('w')||keys.has('ArrowUp')?1:0)-(keys.has('s')||keys.has('ArrowDown')?1:0),side=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0);camera.position.x=THREE.MathUtils.clamp(camera.position.x+(-Math.sin(yaw)*forward+Math.cos(yaw)*side)*dt*2,-2.5,2.5);camera.position.z=THREE.MathUtils.clamp(camera.position.z+(-Math.cos(yaw)*forward-Math.sin(yaw)*side)*dt*2,galleryLayout.endZ+.5,1.8);}
 camera.rotation.y=yaw;camera.rotation.x=pitch;const ri=Math.max(0,galleryLayout.rooms.findLastIndex(r=>-camera.position.z+1.8>=r.start));if(!motion&&ri!==roomIndex){roomIndex=ri;updateUI();history.replaceState(null,'','#'+roomData.rooms[ri].id);}if(!reduced)for(const s of sculptures)s.light.emissiveIntensity=s.base*(1+.08*Math.sin(now*.0007));if(!$('panel').open)renderer.render(scene,camera);animationFrame=requestAnimationFrame(animate);}

async function boot(){try{const rr=await fetch('./data/rooms.json'),ss=await fetch('./data/sources.json');if(!rr.ok||!ss.ok)throw Error('manifest load');roomData=await rr.json();sources=await ss.json();const lr=await fetch('./data/gallery-layout.json');if(!lr.ok)throw Error('gallery layout');galleryLayout=await lr.json();exhibits=new Map([...sources.items,...extras()].map(e=>[e.id,e]));for(const room of roomData.rooms)for(const id of room.exhibits)if(!exhibits.has(id))throw Error('Missing exhibit '+id);
 $('walk-forward').onclick=()=>walkStep(-2.5);$('walk-back').onclick=()=>walkStep(2.5);$('focus-art').onclick=()=>showExhibit(selectedExhibit);$('overview').onclick=()=>{stopTour();roomView();};$('language').onclick=()=>{lang=lang==='zh'?'en':'zh';updateUI();};$('about').onclick=showAbout;$('room-works').onclick=showWorks;$('close-panel').onclick=closePanel;$('panel').addEventListener('close',()=>{crystalCleanup?.();crystalCleanup=null;});$('panel').addEventListener('click',e=>{if(e.target===$('panel')){const r=$('panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});$('previous').onclick=()=>goRoom(roomIndex-1);$('next').onclick=()=>goRoom(roomIndex+1);$('tour').onclick=startTour;$('motion').onclick=()=>{reduced=!reduced;if(reduced&&motion)motion.duration=0;updateUI();};$('music').ontimeupdate=syncMusic;$('music').onended=syncMusic;$('music').onpause=syncMusic;$('music-toggle').onclick=()=>{if($('music').paused)$('music').play().catch(()=>toast(tx('请重新打开音轨','Please reopen the track')));else $('music').pause();syncMusic();};$('music-stop').onclick=()=>{$('music').pause();$('music').currentTime=0;$('music-bar').hidden=true;syncMusic();};$('narration').onended=()=>{if(!touring)return;if(roomIndex===5){stopTour();return;}tourTimer=setTimeout(()=>{goRoom(roomIndex+1,true);tourTimer=setTimeout(narrate,reduced?100:1900);},1700);};
 updateUI();try{await initWorld();$('loading').hidden=true;}catch(err){console.error(err);$('loading').hidden=true;$('fallback-gallery').hidden=false;$('focus-tools').hidden=true;$('walk-controls').hidden=true;document.body.classList.add('flat-view');updateStrip();}
 const requested=roomData.rooms.findIndex(r=>'#'+r.id===location.hash);if(requested>=0)goRoom(requested);document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(touring)stopTour();}});
 }catch(err){console.error(err);$('loading').innerHTML=tx('资料暂时无法加载。请刷新，或','Unable to load the exhibition. Reload or')+' <a href="./archive.html">'+tx('阅读本版目录','read the edition archive')+'</a>';}}
boot();
